    defaults = {'HIGH': (24, 72), 'MEDIUM': (72, 96), 'LOW': (120, 168)}
    for priority, (response_hours, completion_hours) in defaults.items():
        ServiceLevelPolicy.objects.get_or_create(
            priority=priority,
            defaults={
                'first_response_hours': response_hours,
                'completion_hours': completion_hours,
                'is_approved': False,
            },
        )
    for item in ServiceRequest.objects.exclude(status__in=('COMPLETED', 'CANCELLED')).iterator():
        response_hours, completion_hours = defaults[item.priority]
        ServiceRequest.objects.filter(pk=item.pk).update(
            first_response_due_at=item.created_at + timedelta(hours=response_hours),
            due_at=item.created_at + timedelta(hours=completion_hours),
        )


